package ch.bbw.zork;import java.util.ArrayList;import java.util.HashMap;/** * Stellt einen Raum im Zork-Spiel dar. * Ein Raum besitzt eine Beschreibung, Ausgänge und Gegenstände. * Ein Raum kann ausserdem als Gewinner-Raum definiert werden. */public class Room {	private String description;	private HashMap<String, Room> exits;	private boolean winnerRoom;	private ArrayList<Item> items;	/**	 * Erstellt einen neuen Raum.	 *	 * @param description Beschreibung des Raumes	 */	public Room(String description) {		this.description = description;		this.exits = new HashMap<>();		this.winnerRoom = false;		this.items = new ArrayList<>();	}	/**	 * Legt die Ausgänge des Raumes fest.	 *	 * @param north Raum im Norden	 * @param east Raum im Osten	 * @param south Raum im Süden	 * @param west Raum im Westen	 */	public void setExits(Room north, Room east, Room south, Room west) {		exits.put("north", north);		exits.put("east", east);		exits.put("south", south);		exits.put("west", west);	}	/**	 * Gibt die kurze Beschreibung des Raumes zurück.	 *	 * @return Beschreibung des Raumes	 */	public String shortDescription() {		return description;	}	/**	 * Gibt die Beschreibung, Ausgänge und Gegenstände des Raumes zurück.	 *	 * @return vollständige Beschreibung des Raumes	 */	public String longDescription() {		StringBuilder stringBuilder =				new StringBuilder("You are in " + description + ".\n");		stringBuilder.append(exitString());		if (!items.isEmpty()) {			stringBuilder.append("\nItems:");			for (Item item : items) {				stringBuilder.append("\n- ").append(item);			}		}		return stringBuilder.toString();	}	/**	 * Gibt die möglichen Ausgänge des Raumes zurück.	 *	 * @return mögliche Ausgänge	 */	private String exitString() {		ArrayList<String> possibleExits = new ArrayList<>();		for (String direction : exits.keySet()) {			if (exits.get(direction) != null) {				possibleExits.add(direction);			}		}		return "Exits: " + String.join(" ", possibleExits);	}	/**	 * Gibt den nächsten Raum in einer bestimmten Richtung zurück.	 *	 * @param direction gewünschte Richtung	 * @return nächster Raum oder null, wenn kein Ausgang vorhanden ist	 */	public Room nextRoom(String direction) {		return exits.get(direction);	}	/**	 * Legt fest, ob dieser Raum der Gewinner-Raum ist.	 *	 * @param winnerRoom true, wenn dieser Raum der Gewinner-Raum ist	 */	public void setWinnerRoom(boolean winnerRoom) {		this.winnerRoom = winnerRoom;	}	/**	 * Prüft, ob dieser Raum der Gewinner-Raum ist.	 *	 * @return true, wenn dieser Raum der Gewinner-Raum ist	 */	public boolean isWinnerRoom() {		return winnerRoom;	}	/**	 * Fügt einen Gegenstand zum Raum hinzu.	 *	 * @param item Gegenstand, der hinzugefügt wird	 */	public void addItem(Item item) {		items.add(item);	}	/**	 * Entfernt einen Gegenstand aus dem Raum.	 *	 * @param item Gegenstand, der entfernt wird	 */	public void removeItem(Item item) {		items.remove(item);	}	/**	 * Sucht einen Gegenstand anhand seines Namens.	 *	 * @param name Name des gesuchten Gegenstandes	 * @return gefundener Gegenstand oder null	 */	public Item getItem(String name) {		for (Item item : items) {			if (item.getName().equalsIgnoreCase(name)) {				return item;			}		}		return null;	}	/**	 * Gibt alle Gegenstände im Raum zurück.	 *	 * @return Liste mit allen Gegenständen	 */	public ArrayList<Item> getItems() {		return items;	}}